/**
 * Get the identity for the given header.
 *
 * @param {nsIMsgDBHdr} hdr - Message header.
 * @param {nsIMsgCompType} type - Compose type the identity is used for.
 * @returns {Array} - An array of two elements, [identity, matchingHint].
 *   identity is an nsIMsgIdentity and matchingHint is a string.
 */
getIdentityForHeader(hdr, type, hint = "") {
  let server = null;
  let identity = null;
  let matchingHint = null;
  const folder = hdr.folder;
  if (folder) {
    server = folder.server;
    identity = folder.customIdentity;
    if (identity) {
      return [identity, null];
    }

openListURL(event) {
  const url = event.target.value;
  if (url.startsWith("mailto:")) {
    const [identity] = MailUtils.getIdentityForHeader(gMessage);
    top.composeEmailTo(url, identity);
    return;
  }
  openUILink(url, event);

handleLinkEvent(event) {
  if (
    (event.type == "click" && event.button != 2) ||
    (event.type == "keydown" && event.key == "Enter")
  ) {
    event.preventDefault();
    if (event.target.href.startsWith("mailto:")) {
      const [identity] = lazy.MailUtils.getIdentityForHeader(gMessage);
      top.composeEmailTo(event.target.href, identity);
      return;
    }
    openUILink(event.target.href, event);
